import sys


def main():
    data = sys.stdin.read().splitlines()
    n = int(data[0].strip())
    names = []
    sums = []
    for line in data[1:1 + n]:
        state = 0
        name = ''
        sign = 1
        q = 0
        p = 0
        for c in line + ',':
            if c == ' ':
                continue
            if c == ',':
                prod = sign * q * p
                if name in names:
                    sums[names.index(name)] += prod
                else:
                    names.append(name)
                    sums.append(prod)
                state = 0
                name = ''
                sign = 1
                q = 0
                p = 0
            elif c == ':':
                state = 1
            elif c == '*':
                state = 2
            elif state == 0:
                name += c
            elif state == 1:
                if c == '-':
                    sign = -1
                else:
                    q = q * 10 + ord(c) - 48
            else:
                p = p * 10 + ord(c) - 48
    for i in range(len(names)):
        print(names[i], sums[i])


main()
